def calc_xor(cmd, data):
    x = FRAME_HEADER ^ cmd
    dl = len(data)
    x ^= (dl >> 8) & 0xFF
    x ^= dl & 0xFF
    for b in data:
        x ^= b
    return x & 0xFF

