        self.device_key = "a1b2c3d4e5f6"

        self.frame_receiver = FrameReceiver()
        self.ipgeo = IPGeolocation()

        self.log_queue = deque(maxlen=500)
        self.last_heartbeat = 0
        self.heartbeat_interval = 60

        self._lock = threading.Lock()

